using System.Security.Cryptography;
using System.Net;
namespace SoloCamera.Windows;
public static class SelfTest {
 public static async Task Run(string output){var results=new List<string>();void Check(bool condition,string name){if(!condition)throw new Exception(name);results.Add("PASS "+name);}try{using var aes=new AesGcm(new byte[16],16);byte[] plain=[1,2,3,4],encrypted=PhoneConnection.Encrypt(aes,plain,1,0);Check(PhoneConnection.Decrypt(aes,encrypted,1,0).SequenceEqual(plain),"Authenticated packet roundtrip");bool rejected=false;try{PhoneConnection.Decrypt(aes,encrypted,1,1);}catch(CryptographicException){rejected=true;}Check(rejected,"Replay rejected at next sequence");encrypted[0]^=1;rejected=false;try{PhoneConnection.Decrypt(aes,encrypted,1,0);}catch(CryptographicException){rejected=true;}Check(rejected,"Tampering rejected");using var camera=new PhoneConnection();rejected=false;try{camera.Connect("bad","bad");}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid pairing rejected");byte[] audio=new byte[1933];audio[0]=5;System.Buffers.Binary.BinaryPrimitives.WriteInt64BigEndian(audio.AsSpan(1),123456);System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(audio.AsSpan(9),48000);for(int i=0;i<30;i++)camera.AcceptAudio(audio);Check(camera.AudioAfter(0).Length==16,"Audio queue bounded to 320ms");Check(camera.AudioAfter(29).Length==1,"Audio cursor avoids duplicate playback");bool invalidAudio=false;try{camera.AcceptAudio(new byte[2]);}catch(IOException){invalidAudio=true;}Check(invalidAudio,"Malformed audio rejected");using var server=new LocalFeedServer([camera]);using var http=new HttpClient();Check((await http.GetAsync(server.Url)).StatusCode==HttpStatusCode.OK,"Clean feed served without administrator rights");Check((await http.GetAsync($"http://127.0.0.1:{server.Port}/wrong/feed")).StatusCode==HttpStatusCode.Forbidden,"Feed access token enforced");Check((await http.GetAsync(server.Url.Replace("/feed","/frame/0"))).StatusCode==HttpStatusCode.NoContent,"Disconnected camera returns no stale frame");var qr=PairingWindow.CreateQrBitmap("solocamera-desktop:1:192.168.1.20:49123:0123456789abcdef0123456789abcdef");var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(qr));using(var file=File.Create(Path.ChangeExtension(output,"qr.png")))encoder.Save(file);Check(qr.PixelWidth>200,"Desktop QR bitmap generated");results.Add("SUCCESS");}catch(Exception e){results.Add("FAIL "+e);}await File.WriteAllLinesAsync(output,results);}
}

